function present(value) {
  return value !== undefined && value !== null && String(value).trim() !== '';
}

function getPath(source, path) {
  return path.split('.').reduce((value, key) => (value && value[key] !== undefined ? value[key] : undefined), source);
}

function pick(source, names) {
  for (const name of names) {
    const value = name.includes('.') ? getPath(source, name) : source[name];
    if (present(value)) return value;
  }
  return '';
}

function bool(value) {
  return value === true || ['true', 'yes', '1', 'subscribed', 'allowed', 'opted in', 'opt-in', 'ok'].includes(String(value ?? '').trim().toLowerCase());
}

function cleanPhone(value) {
  if (!present(value)) return '';
  const text = String(value).trim();
  if (text.startsWith('+')) return '+' + text.slice(1).replace(/\D/g, '');
  return text.replace(/[^\d+]/g, '');
}

function compact(text) {
  return String(text || '').replace(/\s+/g, ' ').trim();
}

function withOptOut(message) {
  const text = compact(message);
  const finalText = /\bstop\b/i.test(text) ? text : `${text} Reply STOP to opt out.`;
  return finalText.length > 320 ? `${finalText.slice(0, 317)}...` : finalText;
}

const payload = $json.body ?? $json;
const order = payload.order ?? payload.data ?? payload;
const statusAliases = {
  pending: 'pending',
  processing: 'processing',
  processed: 'processing',
  paid: 'processing',
  shipped: 'shipped',
  dispatched: 'shipped',
  dispatch: 'shipped',
  'out for delivery': 'out_for_delivery',
  out_for_delivery: 'out_for_delivery',
  outfordelivery: 'out_for_delivery',
  complete: 'delivered',
  completed: 'delivered',
  delivered: 'delivered',
  canceled: 'canceled',
  cancelled: 'canceled',
  failed: 'failed',
  voided: 'failed',
  refunded: 'refunded',
  refund: 'refunded'
};

const rawStatus = compact(pick(order, ['order_status', 'orderStatus', 'order_status_name', 'status_name', 'status', 'history.status', 'order.order_status'])).toLowerCase().replace(/[\-_]+/g, ' ');
const orderStatus = statusAliases[rawStatus] || rawStatus.replace(/\s+/g, '_');
const supportedStatuses = ['pending', 'processing', 'shipped', 'out_for_delivery', 'delivered', 'canceled', 'failed', 'refunded'];
const orderId = compact(pick(order, ['order_id', 'orderId', 'id', 'order.order_id']));
const orderDate = compact(pick(order, ['order_date', 'orderDate', 'date_added', 'dateAdded']));
const orderTotal = compact(pick(order, ['order_total', 'orderTotal', 'total', 'totals.total']));
const firstName = compact(pick(order, ['firstname', 'first_name', 'customer.firstname', 'customer.first_name', 'payment_firstname', 'shipping_firstname'])) || 'there';
const storeName = compact(pick(order, ['store_name', 'storeName', 'store.name'])) || 'our store';
const storeUrl = compact(pick(order, ['store_url', 'storeUrl', 'store.url']));
const shippingMethod = compact(pick(order, ['shipping_method', 'shippingMethod', 'shipping.method']));
const phone = cleanPhone(pick(order, ['telephone', 'phone', 'customer_phone', 'customer.telephone', 'customer.phone', 'payment_telephone', 'shipping_phone', 'shipping_telephone']));
const channelValue = compact(pick(order, ['channel', 'message_channel', 'messageChannel'])).toLowerCase();
const channel = ['sms', 'whatsapp'].includes(channelValue) ? channelValue : 'sms';
const trackingNumber = compact(pick(order, ['tracking_number', 'trackingNumber', 'tracking.code', 'shipment.tracking_number']));
const trackingUrl = compact(pick(order, ['tracking_url', 'trackingUrl', 'tracking.url', 'shipment.tracking_url']));
const consent = bool(pick(order, ['sms_consent', 'smsConsent', 'transactional_sms_allowed', 'transactionalSmsAllowed', 'consent', 'opt_in', 'customer.sms_consent', 'customer.transactional_sms_allowed']));
const optedOut = bool(pick(order, ['sms_opt_out', 'smsOptOut', 'opt_out', 'do_not_sms', 'unsubscribe', 'customer.sms_opt_out', 'customer.opt_out']));
const totalText = orderTotal ? ` Total: ${orderTotal}.` : '';
const dateText = orderDate ? ` Date: ${orderDate}.` : '';
const shippingText = shippingMethod ? ` Shipping: ${shippingMethod}.` : '';
const storeText = storeUrl ? ` ${storeUrl}` : '';
const trackingText = trackingUrl ? ` Track: ${trackingUrl}` : (trackingNumber ? ` Tracking: ${trackingNumber}` : '');
const messages = {
  pending: `Hi ${firstName}, ${storeName} received order #${orderId}.${totalText}${dateText}`,
  processing: `Hi ${firstName}, ${storeName} is processing order #${orderId}.${totalText}${shippingText}`,
  shipped: `Hi ${firstName}, order #${orderId} from ${storeName} has shipped.${trackingText}`,
  out_for_delivery: `Hi ${firstName}, order #${orderId} from ${storeName} is out for delivery today.${trackingText}`,
  delivered: `Hi ${firstName}, order #${orderId} from ${storeName} was delivered. Thank you for shopping with us.${storeText}`,
  canceled: `Hi ${firstName}, order #${orderId} from ${storeName} was canceled. Contact support if this was unexpected.`,
  failed: `Hi ${firstName}, payment for order #${orderId} at ${storeName} did not complete. Please check your order or contact support.`,
  refunded: `Hi ${firstName}, refund processing has started for order #${orderId} from ${storeName}.`
};
const errors = [];

if (!orderId) errors.push('Missing order_id');
if (!orderStatus) errors.push('Missing order_status');
if (orderStatus && !supportedStatuses.includes(orderStatus)) errors.push(`Unsupported order status: ${orderStatus}`);
if (!phone) errors.push('Missing customer phone');
if (!consent) errors.push('Missing SMS consent');
if (optedOut) errors.push('Customer opted out of SMS');

const shouldSend = errors.length === 0;

return [{
  json: {
    shouldSend,
    skipReason: errors.join('; '),
    orderId,
    orderStatus,
    phone,
    channel,
    firstName,
    storeName,
    storeUrl,
    orderDate,
    orderTotal,
    shippingMethod,
    trackingNumber,
    trackingUrl,
    message: shouldSend ? withOptOut(messages[orderStatus]) : '',
    referenceId: orderId && orderStatus ? `opencart-${orderId}-${orderStatus}` : '',
  },
}];
